package com.eia.retrocession.expert;

import com.fasterxml.jackson.annotation.JsonFormat;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.UUID;

/**
 * Assumed-book retrocession aggregate persisted by the expert.
 *
 * <p>The retrocession number is generated by the expert. The aggregate is fixed
 * to the ASSUMED book (SPEC 3.6.1 and 11.10.1).</p>
 */
public record Retrocession(
        UUID id,
        UUID tenantId,
        String businessBook,
        String retrocessionNumber,
        UUID contractId,
        UUID retroContractId,
        RetrocessionStatus status,
        @JsonFormat(shape = JsonFormat.Shape.STRING) BigDecimal cededPremium,
        @JsonFormat(shape = JsonFormat.Shape.STRING) BigDecimal cededLoss,
        String currency,
        int version,
        Instant createdAt,
        Instant updatedAt,
        String fsriHandoffId,
        String fsriStatus,
        Instant fsriHandedOffAt,
        String fsriLastError
) {
    public Retrocession(UUID id,
                        UUID tenantId,
                        String businessBook,
                        String retrocessionNumber,
                        UUID contractId,
                        UUID retroContractId,
                        RetrocessionStatus status,
                        BigDecimal cededPremium,
                        BigDecimal cededLoss,
                        String currency,
                        int version,
                        Instant createdAt,
                        Instant updatedAt) {
        this(id, tenantId, businessBook, retrocessionNumber, contractId, retroContractId, status,
                cededPremium, cededLoss, currency, version, createdAt, updatedAt,
                null, null, null, null);
    }
}
